def rattacher_les_missions(apps, schema_editor):
    """Une mission existante est rattachée à l'institution de sa première équipe : c'est elle
    qui la commandait de fait. Les missions sans équipe restent sans institution."""
    Mission = apps.get_model("core", "Mission")
    for mission in Mission.objects.filter(institution__isnull=True).prefetch_related("equipes"):
        equipes = sorted(mission.equipes.all(), key=lambda equipe: str(equipe.pk))
        institution_id = next((e.institution_id for e in equipes if e.institution_id), None)
        if institution_id:
            Mission.objects.filter(pk=mission.pk).update(institution_id=institution_id)


